-- Batch 04: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v6';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=4; expected_before int:=66; expected_added int:=18;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v6_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"5454dcdb-e695-4b02-8dad-e0158dc37cde","f":"facade_type","type":"text","value":"双重隔热单元式玻璃幕墙","unit":"configuration","sources":[{"url":"https://www.wsp.com/zh-cn/projects/leeza-soho-beijing","name":"项目机电顾问WSP","tier":"primary"},{"url":"https://www.gooood.cn/en/leeza-soho-china-by-zaha-hadid-architects.htm","name":"谷德设计网（建筑设计资料）","tier":"authoritative_secondary"}],"note":"机电顾问和建筑设计资料独立支持双重隔热单元式玻璃幕墙"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"grade","type":"text","value":"国际甲级","unit":"brochure_positioning","sources":[{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=1797&m=content","name":"人寿集团地产运营部资料（公开招商平台）","tier":"secondary"},{"url":"https://www.xzlsd.com/office_detail/3620.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"同址针织路23号；国际甲级是招商定位，非市场等级"},{"id":"6ea640bb-16c3-40f4-9c6b-840b690f0148","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.jiandadasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.bj-jdds.cn/","name":"北京写字楼信息平台","tier":"secondary"}],"note":"同址东土城路14号；不同渠道的项目参数共同支持，停车和总层数有冲突未采用"},{"id":"6ea640bb-16c3-40f4-9c6b-840b690f0148","f":"floor_height","type":"numeric","value":3.2,"unit":"m","sources":[{"url":"https://www.jiandadasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.bj-jdds.cn/","name":"北京写字楼信息平台","tier":"secondary"}],"note":"同址东土城路14号；不同渠道的项目参数共同支持，停车和总层数有冲突未采用"},{"id":"6ea640bb-16c3-40f4-9c6b-840b690f0148","f":"telecom_provider","type":"text","value":"电信、联通、卫通、有线通（历史公开配置）","unit":"configuration","sources":[{"url":"https://www.jiandadasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.bj-jdds.cn/","name":"北京写字楼信息平台","tier":"secondary"}],"note":"同址东土城路14号；不同渠道的项目参数共同支持，停车和总层数有冲突未采用"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.bjzsjds.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://www.zhaoshangjv.cn/","name":"招商局大厦公开招商网","tier":"secondary"}],"note":"建国路118号；办公楼招商定位"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"floors_above","type":"integer","value":32,"unit":"floor","sources":[{"url":"https://www.office-beijing.com/office/1576.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://www.taogongwei.com/sharedSpace/detail/1084","name":"淘工位（寰图招商局大厦项目）","tier":"secondary"}],"note":"办公楼地上32层地下2层，合计34；两渠道均写中央空调；不采用综合体面积、停车及存在冲突的梯数"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"floors_below","type":"integer","value":2,"unit":"floor","sources":[{"url":"https://www.office-beijing.com/office/1576.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://www.taogongwei.com/sharedSpace/detail/1084","name":"淘工位（寰图招商局大厦项目）","tier":"secondary"}],"note":"办公楼地上32层地下2层，合计34；两渠道均写中央空调；不采用综合体面积、停车及存在冲突的梯数"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"building_floors","type":"integer","value":34,"unit":"floor","sources":[{"url":"https://www.office-beijing.com/office/1576.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://www.taogongwei.com/sharedSpace/detail/1084","name":"淘工位（寰图招商局大厦项目）","tier":"secondary"}],"note":"办公楼地上32层地下2层，合计34；两渠道均写中央空调；不采用综合体面积、停车及存在冲突的梯数"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"hvac_system","type":"text","value":"中央空调","unit":"configuration","sources":[{"url":"https://www.office-beijing.com/office/1576.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://www.taogongwei.com/sharedSpace/detail/1084","name":"淘工位（寰图招商局大厦项目）","tier":"secondary"}],"note":"办公楼地上32层地下2层，合计34；两渠道均写中央空调；不采用综合体面积、停车及存在冲突的梯数"},{"id":"2159ec01-7b8a-42fb-9262-167076687a03","f":"facade_type","type":"text","value":"花岗岩与玻璃单元式幕墙","unit":"configuration","sources":[{"url":"https://www.zhaoshangjudasha.cn/index.html","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/1576.html","name":"北京写字楼门户","tier":"secondary"}],"note":"两源明确花岗岩与玻璃外墙，后者详细列单元式幕墙"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.beichenhuixin.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://office-beijing.com/office/218.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址北辰东路8号，公开招商定位"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"floor_load_office","type":"integer","value":200,"unit":"kg/m2","sources":[{"url":"https://m.mingdefang.cn/beijingshi/zufang/295.html","name":"明德房产","tier":"secondary"},{"url":"https://bj5a-office.com/bencandy.php?fid=75&id=630","name":"北京写字楼租赁网","tier":"secondary"}],"note":"同址办公楼板承重均列200kg/㎡"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"telecom_provider","type":"text","value":"电信、移动（历史公开配置）","unit":"configuration","sources":[{"url":"https://www.beichenhuixin.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.xzlsd.com/office_detail/826.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"两源网络配置共同列电信和移动"},{"id":"0bb85d6d-88c5-4d12-b09b-4a42d10aacd8","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.anjigao.com/index.php/house/show/id/868.shtml","name":"安居高","tier":"secondary"},{"url":"https://www.xzlsd.com/m/rent_x.aspx?proId=3663","name":"首都写字楼出租网","tier":"secondary"}],"note":"同址知春路76号原翠宫饭店改造办公项目；共同支持70%使用率和甲级定位"},{"id":"0bb85d6d-88c5-4d12-b09b-4a42d10aacd8","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.anjigao.com/index.php/house/show/id/868.shtml","name":"安居高","tier":"secondary"},{"url":"https://www.xzlsd.com/m/rent_x.aspx?proId=3663","name":"首都写字楼出租网","tier":"secondary"}],"note":"同址知春路76号原翠宫饭店改造办公项目；共同支持70%使用率和甲级定位"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"developer","type":"text","value":"北京市大地科技实业总公司","unit":"company","sources":[{"url":"https://www.bjzgcgjcx.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://www.bj-sydc.com/dasha/1263.html","name":"北京商业地产楼宇信息","tier":"secondary"}],"note":"原大地科技大厦，北四环西路67号；两源一致开发主体及客梯2部，未采用面积冲突"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"elevator_passenger","type":"integer","value":2,"unit":"count","sources":[{"url":"https://www.bjzgcgjcx.cn/","name":"北京写字楼信息平台","tier":"secondary"},{"url":"https://www.bj-sydc.com/dasha/1263.html","name":"北京商业地产楼宇信息","tier":"secondary"}],"note":"原大地科技大厦，北四环西路67号；两源一致开发主体及客梯2部，未采用面积冲突"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v6_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v6_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
COMMIT;